impl Catalogued for Nakshatra {
    const KIND: Kind = Kind::Nakshatra;

    fn all() -> &'static [Self] {
        &Self::ALL
    }

    fn key(self) -> &'static str {
        self.key()
    }

    fn id(self) -> u16 {
        self.id()
    }

    fn mark(self) -> Mark {
        self.mark()
    }

    fn from_key(key: &str) -> Option<Self> {
        Self::from_key(key)
    }

    fn from_id(id: u16) -> Option<Self> {
        Self::from_id(id)
    }
}

impl core::fmt::Display for Nakshatra {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.write_str(self.key())
    }
}

impl core::str::FromStr for Nakshatra {
    type Err = UnknownKey;

    fn from_str(key: &str) -> Result<Self, UnknownKey> {
        Self::from_key(key).ok_or_else(|| UnknownKey::in_kind::<Nakshatra>(key))
    }
}

impl From<Nakshatra> for KeyId {
    fn from(member: Nakshatra) -> KeyId {
        member.key_id()
    }
}

impl TryFrom<KeyId> for Nakshatra {
    type Error = UnknownKey;

    fn try_from(id: KeyId) -> Result<Self, UnknownKey> {
        match id.kind() {
            Some(Kind::Nakshatra) => Self::from_id(id.id()).ok_or_else(|| UnknownKey::id(id)),
            _ => Err(UnknownKey::id(id)),
        }
    }
}

impl serde::Serialize for Nakshatra {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.serialize_str(self.key())
    }
}

impl<'de> serde::Deserialize<'de> for Nakshatra {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        let key = <&str>::deserialize(deserializer)?;
        Self::from_key(key).ok_or_else(|| serde::de::Error::custom(UnknownKey::in_kind::<Nakshatra>(key)))
    }
}
